-- Benchmark seed: live Indian startup comparables with sourced valuations.
-- 30 rows, researched and sourced; re-runnable (upsert on startup_name).

on conflict (startup_name) do update set sector_slug = excluded.sector_slug, subsector = excluded.subsector, founded_year = excluded.founded_year, hq_city = excluded.hq_city, stage = excluded.stage, total_funding_usd = excluded.total_funding_usd, last_round = excluded.last_round, last_round_date = excluded.last_round_date, valuation_usd = excluded.valuation_usd, valuation_display = excluded.valuation_display, key_metric = excluded.key_metric, founding_story = excluded.founding_story, student_relevance = excluded.student_relevance, source_url = excluded.source_url, as_of_date = excluded.as_of_date;
