insert into public.benchmarks (startup_name, sector_slug, subsector, founded_year, hq_city, stage, total_funding_usd, last_round, last_round_date, valuation_usd, valuation_display, key_metric, founding_story, student_relevance, source_url, as_of_date) values
  ('Sarvam AI', 'ai_ml', 'Sovereign LLMs & Indic voice AI', 2023, 'Bengaluru', 'unicorn', 275000000, '$234M Series B first close (HCLTech-led, of $300M target)', '2026-06', 1500000000, '$1.5B (Jun 2026, Series B)', 'India''s newest AI unicorn and the IndiaAI Mission''s pick to build a sovereign foundational LLM from scratch; HCLTech invested $150M for a 10%+ stake', 'Co-founders Vivek Raghavan and Pratyush Kumar worked together at AI4Bharat, the IIT Madras open-source lab building Indic-language AI, before founding Sarvam in 2023. Three years later, backed by Lightspeed, Peak XV, Khosla, Bessemer and HCLTech, it became India''s flagship sovereign-AI company.', 'Shows how research done inside a campus AI lab (AI4Bharat at IIT Madras) can convert into a $1.5B national-champion company within three years.', 'https://techcrunch.com/2026/06/15/sarvam-becomes-indias-newest-ai-unicorn-with-234-million-funding-round-led-by-hcltech/', '2026-08'),
  ('Krutrim', 'ai_ml', 'Foundation models & AI cloud', 2023, 'Bengaluru', 'unicorn', 304000000, '$50M at $1B (Z47/Matrix-led); founder-led infusions since, incl. a ~Rs 2,000 Cr commitment', '2024-01', 1000000000, '$1B (Jan 2024) — India''s first AI unicorn', 'Fastest Indian startup ever to unicorn (~1 month after launching its LLM); by 2026 it pivoted from frontier-model ambitions to GPU cloud services (Krutrim Cloud)', 'Founded in 2023 by Ola''s Bhavish Aggarwal to build ''India''s own AI'', Krutrim hit a $1B valuation within weeks of unveiling its first LLM in January 2024. By 2026 the economics of competing with OpenAI-scale labs pushed it to refocus on AI cloud infrastructure — a live case study in ambition meeting capital reality.', 'Teaches the brutal unit economics of foundation models and why even a billion-dollar startup may pivot from models to infrastructure.', 'https://techcrunch.com/2026/05/05/indias-first-genai-unicorn-shifts-to-cloud-services-as-ai-model-ambitions-face-reality/', '2026-08'),
  ('Neysa', 'ai_ml', 'AI acceleration cloud (GPU-as-a-service)', 2023, 'Mumbai', 'growth', 650000000, 'Up to $600M equity (Blackstone-led) + $600M planned debt — a $1.2B capital raise', '2026-02', null, 'Undisclosed; Blackstone took a majority stake in the Feb 2026 deal (~$1.4B enterprise value reported)', 'One of the largest-ever private-equity cheques into an Indian AI startup — capital earmarked to deploy 20,000+ GPUs across India for sovereign AI compute', 'Founded in 2023 by Sharad Sanghi — who had earlier built Netmagic, India''s largest data-center company (acquired by NTT) — and Anindya Das. In under three years it went from a $20M seed to a Blackstone-led $1.2B capital raise to become India''s AI-infrastructure backbone.', 'The picks-and-shovels lesson: while everyone builds AI apps, the compute layer underneath attracted India''s biggest AI cheque.', 'https://www.blackstone.com/news/press/blackstone-leads-funding-of-over-1-billion-to-neysa-to-work-towards-building-indias-leading-ai-infrastructure-platform/', '2026-08'),
  ('CoRover (BharatGPT)', 'ai_ml', 'Conversational AI for govt & enterprise', 2016, 'Bengaluru', 'early', 4000000, '$4M Series A (Venture Catalysts-led; IIM Calcutta Innovation Park & IIIT-Delhi iHub participated)', '2024-09', null, 'Undisclosed', 'Builds BharatGPT and AskDISHA, the IRCTC/Indian Railways assistant with voice-UPI ticket payments — claims 1Bn+ users reached across 100+ languages', 'Ankush Sabharwal and co-founders built CoRover from 2016 on a frugal ''revenue-first'' model, winning marquee public deployments — IRCTC''s AskDISHA, NPCI, LIC, Delhi Metro — long before raising a $4M Series A in 2024. Academic-linked funds from IIM Calcutta and IIIT-Delhi are on its cap table.', 'Proof you don''t need $100M to ship AI that millions use daily — distribution through government and enterprise partnerships can beat raw capital.', 'https://entrackr.com/2024/09/venture-catalysts-leads-4-mn-series-a-round-in-corover/', '2026-08'),
  ('Agnikul Cosmos', 'spacetech', 'Small-lift launch vehicles (3D-printed engines)', 2017, 'Chennai', 'growth', 58000000, '$17M (Rs 150 Cr) strategic round — family offices, HDFC Bank, Artha Select, 100X.VC', '2025-11', 500000000, '$500M (Nov 2025)', 'Agnibaan SOrTeD (May 2024): world''s first flight of a single-piece 3D-printed rocket engine, India''s first semi-cryogenic engine flight, and first launch from a private Indian launchpad', 'Srinath Ravichandran, a finance professional who switched careers in his 30s, teamed up with operations expert Moin SPM and IIT Madras combustion professor S.R. Chakravarthy to found Agnikul in 2017 — incubated inside IIT Madras'' National Centre for Combustion R&D, where its rockets were literally built on campus.', 'The definitive proof that an Indian campus lab can incubate a rocket company — from IIT Madras incubation cell to a $500M launch startup.', 'https://www.business-standard.com/companies/start-ups/spacetech-major-agnikul-raises-17-mn-in-funding-round-at-500-mn-valuation-125112200175_1.html', '2026-08'),
  ('Skyroot Aerospace', 'spacetech', 'Orbital launch vehicles (Vikram series)', 2018, 'Hyderabad', 'unicorn', 160000000, '$60M Series C (Sherpalo, GIC, BlackRock, Arkam, Playbook)', '2026-05', 1100000000, '$1.1B (May 2026) — India''s first spacetech unicorn', 'Vikram-S (Nov 2022) was the first privately built Indian rocket to reach space; $160M equity raised across 9 rounds, the most of any Indian launch startup', 'Pawan Kumar Chandana and Naga Bharath Daka were young ISRO scientists who quit the space agency in 2018 to prove private Indian rockets were possible. Four years later Vikram-S made history in mission ''Prarambh'', and in May 2026 Skyroot became India''s first space unicorn.', 'Shows a public-sector engineering job is a launchpad, not a ceiling — two ISRO scientists in their 20s built a $1.1B rocket company.', 'https://www.satellitetoday.com/finance/2026/05/07/skyroot-secures-60m-in-funding-becoming-indias-first-space-unicorn/', '2026-08'),
  ('Pixxel', 'spacetech', 'Hyperspectral earth-imaging satellites', 2019, 'Bengaluru', 'growth', 95000000, '$24M Series B extension (taking Series B to $60M; Google among backers)', '2024-12', null, '~$200M+ (Dec 2024 est.); reported in talks for $80-100M at ~$400M (mid-2026, unclosed)', 'Launched the world''s highest-resolution commercial hyperspectral satellites — first three ''Firefly'' satellites flew on SpaceX Transporter-12 in Jan 2025; counts NASA among customers', 'Awais Ahmed and Kshitij Khandelwal founded Pixxel in 2019 while still final-year students at BITS Pilani, after leading its Hyperloop student team. Six years on, their ''health monitor for the planet'' flies the sharpest commercial hyperspectral cameras in orbit.', 'Two undergrads with a student-team background out-built global space majors in a niche sensing category — category selection beats company size.', 'https://www.pixxel.space/news/pixxel-raises-24m-in-additional-funding-taking-its-total-series-b-raise-to-60m', '2026-08'),
  ('ideaForge', 'deeptech', 'UAVs / drones (defence & industrial)', 2007, 'Navi Mumbai', 'public', 53800000, 'IPO (Jul 2023) — subscribed 106x, listed at a 90%+ premium', '2023-07', 480000000, 'Rs 4,238 Cr (~$480M) market cap (Aug 2026)', 'India''s largest maker of indigenous UAVs; ranked 3rd globally among dual-use (civil + defence) drone manufacturers (Drone Industry Insights, Dec 2024)', 'IIT Bombay classmates Ankit Mehta, Rahul Singh, Ashish Bhat and Vipul Joshi began building quadrotors in their campus lab in the mid-2000s — an early prototype even appeared in the film ''3 Idiots''. Founded in 2007 and largely self-funded for its first eight years, ideaForge drones were deployed after the 26/11 attacks and it IPO''d in 2023.', 'A college robotics project that became a listed defence company — patience (16 years to IPO) is a legitimate startup strategy.', 'https://www.screener.in/company/IDEAFORGE/consolidated/', '2026-08'),
  ('Tonbo Imaging', 'deeptech', 'Night-vision & electro-optics for defence', 2012, 'Bengaluru', 'growth', 44400000, 'Rs 175 Cr (~$21M) Series D pre-IPO (Florintree, Tenacity, EXIM Bank of India)', '2025-04', 180000000, 'Rs 1,500 Cr (~$180M) at Apr 2025 pre-IPO round; DRHP filed with SEBI Dec 2025', 'India''s biggest defence-optics OEM: FY25 revenue Rs 469 Cr with 65% from exports; night-vision and imaging systems sold to militaries across multiple continents', 'Imaging-systems veteran Arvind Lakshmikumar founded Tonbo in Bengaluru in 2012 with Cecilia D''Souza and Ankit Kumar, betting that India could design world-class military electro-optics rather than import them. Qualcomm-backed and export-led, it filed for an IPO in December 2025.', 'Demonstrates that hard, unglamorous engineering (thermal imaging, optics) compounds into defensible export businesses as India''s defence procurement opens up.', 'https://ipocentral.in/tonbo-imaging-ipo-drhp-filing/', '2026-08'),
  ('QpiAI', 'deeptech', 'Full-stack quantum computing + AI', 2019, 'Bengaluru', 'early', 32000000, '$32M Series A co-led by Avataar Ventures and India''s National Quantum Mission', '2025-07', 162000000, '$162M post-money (Jul 2025)', 'Unveiled QpiAI-Indus (Apr 2025), India''s largest quantum computer at 25 superconducting qubits, built under the National Quantum Mission; employs 25+ PhDs', 'Former Nvidia and Qualcomm executive Dr Nagendra Nagaraja founded QpiAI in 2019 to build India''s quantum stack end-to-end — chips, control systems and software. Its Series A was co-led by the Government of India''s National Quantum Mission, a first-of-its-kind public co-investment.', 'Quantum + AI is the rare frontier where an Indian student entering now competes on nearly equal footing with the world — and government missions now co-fund the startups.', 'https://www.business-standard.com/companies/start-ups/qpiai-raises-32mn-series-a-from-avataar-national-quantum-mission-125071601418_1.html', '2026-08'),
  ('Zoho', 'saas', 'Business software suite (55+ apps)', 1996, 'Chennai', 'unicorn', 0, 'None — bootstrapped since 1996, zero venture capital ever', null, null, 'No external valuation — bootstrapped; FY25 operating revenue Rs 12,313 Cr (~$1.45B), profit Rs 3,191 Cr', 'First bootstrapped Indian software company to cross Rs 12,000 Cr revenue; 100M+ users worldwide with zero dilution — founders kept 100% control for 29 years', 'IIT Madras alumnus Sridhar Vembu and Tony Thomas founded AdventNet in 1996 from a Chennai apartment, renaming it Zoho in 2009. It grew into a global SaaS giant without a rupee of VC, famously hiring rural non-graduates through Zoho Schools of Learning; Vembu stepped back to ''Chief Scientist'' in Jan 2025.', 'The ultimate counter-narrative to fundraising culture: a $1B+ revenue global software company built from India with no investors at all.', 'https://entrackr.com/fintrackr/zoho-reports-rs-12313-cr-revenue-and-rs-3191-cr-profit-in-fy25-11701761', '2026-08'),
  ('Freshworks', 'saas', 'Customer & employee experience software', 2010, 'San Mateo / Chennai', 'public', 400000000, 'IPO on Nasdaq (Sep 2021) — first Indian SaaS company to list in the US, raising ~$1B', '2021-09', 3020000000, '$3.02B market cap on Nasdaq (Aug 2026)', '2025 revenue $838.8M with its first GAAP-profitable year ($183.7M net income); the SaaS company that put Chennai on the global software map', 'Ex-Zoho product leader Girish Mathrubootham and Shan Krishnasamy started Freshdesk in 2010 from Chennai after Girish''s frustration with a broken-TV refund convinced him customer support software could be rebuilt for SMBs. Eleven years later it became the first Indian SaaS company to ring the Nasdaq bell.', 'The Zoho-to-Freshworks lineage shows how joining a great product company is itself startup training — and that global SaaS can be built from Tier-1-adjacent India.', 'https://www.macrotrends.net/stocks/charts/FRSH/freshworks/market-cap', '2026-08'),
  ('Postman', 'saas', 'API development platform', 2014, 'San Francisco / Bengaluru', 'unicorn', 430000000, '$225M Series D (Insight Partners-led)', '2021-08', 5600000000, '$5.6B (Aug 2021) — then India''s most valuable SaaS startup', 'The world''s default API tool: 17M+ developers and 500,000+ organizations at its 2021 round, having grown from a free Chrome extension', 'BITS Pilani graduate Abhinav Asthana built Postman as a side project — a free Chrome extension to ease his own pain testing APIs — while working in Bengaluru. Usage exploded organically among developers worldwide, and in 2014 he founded the company with Ankit Sobti and Abhijit Kane.', 'The canonical side-project-to-unicorn path: solve your own developer pain, give the tool away, and let bottom-up adoption do the selling.', 'https://techcrunch.com/2021/08/18/api-platform-postman-valued-at-5-6-billion-in-225-million-fundraise/', '2026-08'),
  ('Chargebee', 'saas', 'Subscription billing & revenue management', 2011, 'Chennai', 'unicorn', 470000000, '$250M co-led by Tiger Global and Sequoia', '2022-02', 3500000000, '$3.5B (Feb 2022) — valuation doubled in 9 months', 'Powers subscription billing for thousands of global SaaS companies; raised $470M+ while staying Chennai-rooted and remote-first', 'Krish Subramanian and three engineer friends — Rajaraman Santhanam, KP Saravanan and Thiyagarajan T, several of them Zoho alumni — founded Chargebee in Chennai in 2011 to handle the messy plumbing of recurring payments. A decade of patient B2B compounding turned it into a $3.5B unicorn.', 'Boring-but-critical infrastructure (billing) built patiently from a non-metro base can quietly compound into billions — no consumer hype required.', 'https://www.fintechfutures.com/investment-banking/subscription-management-platform-chargebee-valued-at-3-5bn-following-250m-raise', '2026-08'),
  ('Razorpay', 'fintech', 'Payments & business banking', 2014, 'Bengaluru', 'unicorn', 742000000, '$375M Series F at $7.5B (Dec 2021); confidential IPO DRHP filed Jun 2026', '2021-12', 7500000000, '$7.5B (Dec 2021); IPO filed Jun 2026 reportedly targeting $5-6B', 'FY25 revenue Rs 3,783 Cr (+65% YoY); completed its ''reverse flip'' from the US back to India (May 2025) to list on Indian exchanges', 'IIT Roorkee batchmates Harshil Mathur and Shashank Kumar started Razorpay in 2014 after discovering how painful online payments were for small businesses — they famously pitched 100+ bankers before one partnership. It became the first Indian payments company through Y Combinator and a $7.5B giant.', 'Two IIT hostel-mates fixing a problem incumbents ignored (SMB payments UX) built India''s developer-first payments layer — study their API-led wedge.', 'https://www.outlookmoney.com/invest/razorpay-ipo-fintech-firm-files-draft-papers-via-confidential-filing-route-key-details-investors-must-know', '2026-08'),
  ('Zerodha', 'fintech', 'Discount broking & investing', 2010, 'Bengaluru', 'unicorn', 0, 'None — 100% bootstrapped and founder-owned', null, 7700000000, '~Rs 64,800 Cr (~$7.7B) est. (Hurun India Rich List 2024); no external investors', 'India''s most profitable bootstrapped tech company: FY25 net profit Rs 4,237 Cr on revenue Rs 8,847 Cr, built with zero venture capital', 'Nithin Kamath traded stocks through college while working call-center night shifts; in 2010 he and his brother Nikhil — a school dropout who began trading as a teenager — used their own savings to launch a flat-fee brokerage. Zerodha rewrote Indian broking economics without ever raising money.', 'Deep domain obsession (a decade of trading) plus bootstrapping discipline beat venture-funded rivals — profitability is a moat.', 'https://www.entrepreneur.com/en-in/news-and-trends/zerodha-hints-at-pivot-as-revenue-profit-take-a-hit/497904', '2026-08'),
  ('CRED', 'fintech', 'Credit-card payments & premium financial services', 2018, 'Bengaluru', 'unicorn', 1480000000, 'Series H (~Rs 8,550 Cr / ~$900M reported; $540M tranche recorded Jun 22, 2026)', '2026-06', 4500000000, '~$4.5B post-money (Series H, Jun 2026, reported) — rebounding from a $3.5B down round in Jun 2025', 'FY24 revenue Rs 2,473 Cr (+66% YoY) with losses narrowing; survived a 45% valuation cut from its $6.4B peak and re-rated upward within a year', 'Kunal Shah — a philosophy graduate, not an engineer — founded CRED in 2018 after selling FreeCharge, betting that India''s most creditworthy users were the most underserved. Its valuation rollercoaster ($6.4B peak, $3.5B down round, ~$4.5B recovery) is a masterclass in staying alive through cycles.', 'Counterpoint to the teen-engineer myth: a non-technical, second-time founder in his 30s built one of India''s most-watched fintechs on brand and trust design.', 'https://www.finsmes.com/2026/06/cred-raises-approx-900m-in-series-h-at-post-money-valuation-of-4-5-billion.html', '2026-08'),
  ('Groww', 'fintech', 'Retail investing platform', 2016, 'Bengaluru', 'public', 418000000, 'IPO Rs 6,632 Cr (~$750M), listed Nov 12, 2025', '2025-11', 13000000000, 'Market cap touched Rs 1.17 lakh Cr (~$13B) within a week of listing (Nov 2025, stock +94% over IPO price)', 'India''s largest stockbroker by active investors; entered the top-100 most valuable listed Indian companies days after its Nov 2025 debut', 'Four ex-Flipkart colleagues — Lalit Keshre (IIT Bombay), Harsh Jain (IIT Delhi), Neeraj Singh and Ishan Bansal — quit comfortable jobs in 2016 to make investing as simple as e-commerce. Nine years later Groww''s IPO minted one of the strongest listings of 2025.', 'Shows the ''startup employee first, founder second'' path: operating experience at Flipkart gave the team the playbook to out-execute older brokers.', 'https://techcrunch.com/2025/11/12/groww-raises-nearly-750m-in-ipo-as-indias-retail-investing-boom-continues/', '2026-08'),
  ('Ather Energy', 'hardware', 'Electric two-wheelers & charging network', 2013, 'Bengaluru', 'public', 502000000, '$135M post-IPO institutional placement', '2026-07', 6900000000, 'Rs 60,176 Cr (~$6.9B) market cap (Aug 2026) — roughly 4x within a year of its May 2025 IPO (52-wk range Rs 380-1,508)', 'Built India''s first smart electric scooter (Ather 450, 2018) and the Ather Grid fast-charging network; listed May 2025 and its stock ~4x''d in 12 months', 'IIT Madras graduates Tarun Mehta and Swapnil Jain founded Ather in 2013 inside the IIT Madras incubation ecosystem, designing an electric scooter from scratch when everyone imported kits. Early cheques came from Flipkart''s founders, then Hero MotoCorp and Tiger Global, culminating in a 2025 IPO.', 'The flagship campus-to-IPO hardware story: an IIT Madras incubated student project became a listed EV company worth ~$7B.', 'https://www.tickertape.in/stocks/ather-energy-ATHER', '2026-08'),
  ('Exponent Energy', 'hardware', '15-minute rapid charging (battery packs + chargers)', 2020, 'Bengaluru', 'growth', 67000000, 'Rs 200 Cr (~$23M) Series B2 co-led by 360 ONE Asset and TDK Ventures; Hitachi Ventures joined', '2026-06', null, 'Undisclosed', '0-to-100% EV charge in 15 minutes via its paired e^pack battery and e^pump charger — deployed in commercial 3-wheelers and trucks with multiple OEMs', 'Arun Vinayak, Ather''s founding partner and Chief Product Officer, left in 2020 with fellow Ather alum Sanjay Byalal to crack the hardest EV problem: charging speed. Exponent''s full-stack battery-plus-charger system now makes 15-minute rapid charging routine for commercial fleets.', 'Illustrates the ''startup mafia'' effect — early employees of one deeptech success (Ather) spin out to found the next generation.', 'https://entrackr.com/news/exponent-energy-raises-200-cr-in-series-b2-round-led-by-360-one-asset-and-tdk-ventures-12020238', '2026-08'),
  ('Zypp Electric', 'logistics', 'EV fleets for last-mile delivery', 2017, 'Gurugram', 'growth', 75000000, 'Series C tranches: $14M from Japan''s ENEOS (May 2024) + Rs 55.4 Cr (Jan 2025); Tribe Capital-led round targeting ~$40M', '2025-01', 280000000, '~$280M (2024 Series C, up from $175M)', 'One of India''s largest electric last-mile fleets, supplying EV riders and scooters to e-commerce, food and quick-commerce platforms; backed by energy major ENEOS', 'Husband-and-wife co-founders Akash Gupta and Rashi Agarwal started Zypp in 2017 as a scooter-rental service, then pivoted to an EV-fleet-as-a-service model for deliveries — riding the quick-commerce boom while cutting delivery emissions to zero.', 'A pivot masterclass: the same asset (e-scooters) aimed at B2C rentals failed, but aimed at B2B delivery fleets it built a ~$280M company.', 'https://entrackr.com/2024/05/zypp-electric-secures-14-mn-from-eneos/', '2026-08'),
  ('Porter', 'logistics', 'Intra-city on-demand trucking & movers', 2014, 'Bengaluru', 'unicorn', 332000000, '$200M Series F led by Kedaara Capital & Wellington Management', '2025-05', 1200000000, '$1.1-1.2B (May 2025) — one of the first Indian unicorns of 2025', 'Category leader in India''s ~$40B intra-city logistics market; turned unicorn a decade after founding, on improving mini-truck driver economics', 'IIT Kharagpur''s Pranav Goel, IIT Roorkee''s Uttam Digga and Vikas Choudhary founded Porter in 2014 after seeing how idle and underpaid mini-truck drivers were. Their Uber-for-trucks model quietly compounded for 11 years before hitting a $1.2B valuation in 2025.', 'Unsexy, operations-heavy markets reward endurance — Porter took 11 years to unicorn, the opposite of the blitzscaling myth.', 'https://inc42.com/buzz/porter-closes-series-f-round-led-by-kedaara-wellington-management/', '2026-08'),
  ('Zepto', 'consumer', 'Quick commerce (10-minute delivery)', 2021, 'Bengaluru', 'unicorn', 2450000000, '$450M pre-IPO round led by CalPERS', '2025-10', 7000000000, '$7B (Oct 2025); ~$2.45B total raised (Inc42), $900M net cash post-round', 'Founded to $7B in four years — among the fastest value creation in Indian startup history; IPO preparation underway with reported $1.2B pre-IPO plans (2026)', 'Childhood friends Aadit Palicha and Kaivalya Vohra, both 19, dropped out of Stanford''s computer science program during Covid to deliver groceries in 10 minutes from Mumbai dark stores. Kaivalya became the world''s youngest unicorn co-founder as Zepto rocketed to $7B.', 'The ultimate age-is-no-barrier benchmark: two teenagers out-executed Swiggy, Zomato and BigBasket in the hardest operational category in consumer tech.', 'https://indianstartupnews.com/funding/zepto-raises-450-million-at-7-billion-valuation-ceo-palicha-says-we-now-have-900-million-in-cash-10569542', '2026-08'),
  ('boAt (Imagine Marketing)', 'consumer', 'Audio wearables & lifestyle electronics', 2016, 'New Delhi', 'unicorn', 236000000, '$60M at $1.4B (Warburg Pincus/Malabar, Oct 2022); updated DRHP for Rs 1,500 Cr IPO filed Oct 2025', '2022-10', 1400000000, '$1.4B (Oct 2022); IPO-bound with SEBI-approved updated DRHP (Oct 2025)', 'India''s #1 wearables/audio brand; FY25 revenue Rs 3,073 Cr and a return to profit (Rs 61 Cr PAT) ahead of its IPO', 'Aman Gupta, a chartered accountant turned marketer (now a Shark Tank India judge), and Sameer Mehta founded boAt in 2016 with modest personal capital, selling affordable, durable audio gear to young Indians when global brands ignored the sub-Rs 2,000 segment.', 'Proof that branding + distribution is a technology: boAt won consumer electronics with design and marketing insight, not proprietary hardware R&D.', 'https://inc42.com/buzz/boat-files-updated-drhp-for-inr-1500-cr-ipo/', '2026-08'),
  ('Lenskart', 'consumer', 'Omnichannel eyewear', 2010, 'Gurugram', 'public', 981000000, 'IPO Rs 7,278 Cr (~$830M), listed Nov 10, 2025 — subscribed 28x', '2025-11', 8000000000, '~$8B IPO valuation (Nov 2025); India''s 5th-largest IPO of 2025', 'From an online spectacles store in 2010 to one of the world''s largest tech-led eyewear retailers, spanning India, Southeast Asia and Japan (Owndays acquisition)', 'Peyush Bansal left Microsoft in the US, returned to India, and after several e-commerce experiments founded Lenskart in 2010 with Amit Chaudhary and Sumeet Kapahi — vertically integrating manufacturing, brand and stores in a category dominated by unorganized opticians.', 'A 15-year full-stack retail build showing that owning manufacturing + retail + brand (not just an app) creates IPO-grade moats.', 'https://www.business-standard.com/markets/capital-market-news/lenskart-solutions-makes-muted-debut-despite-robust-ipo-demand-125111000300_1.html', '2026-08'),
  ('PhysicsWallah', 'edtech', 'Test prep (JEE/NEET/UPSC) — online + offline', 2020, 'Noida', 'public', 312000000, 'IPO Rs 3,480 Cr, listed Nov 18, 2025 at a 31% premium', '2025-11', 3600000000, '~Rs 31,500 Cr (~$3.6B) at Nov 2025 listing — 79% above its Sep 2024 private valuation of $2.8B (stock corrected in later weeks)', 'The only major Indian edtech to reach IPO; FY25 revenue Rs 2,890 Cr (+49%) with narrowing losses; turned unicorn on its very first $102M funding round (2022)', 'Alakh Pandey, a physics teacher from Prayagraj who had to drop out of his own engineering degree, began teaching free on YouTube in 2016. His channel''s cult following became a company in 2020 with co-founder Prateek Maheshwari — reaching a $1.1B valuation on its maiden round while Byju''s-era edtechs collapsed.', 'The anti-Byju''s benchmark: content quality, trust and frugality (profitable while rivals burned billions) took a YouTube teacher to a stock-exchange listing.', 'https://finance.yahoo.com/news/physics-wallah-enjoys-rosy-ipo-153609759.html', '2026-08'),
  ('Unacademy', 'edtech', 'Online learning & test prep', 2015, 'Bengaluru', 'growth', 860000000, '$440M Series H led by Temasek (with SoftBank, Tiger Global, General Atlantic)', '2021-08', null, 'Peak $3.44B (Aug 2021); founder-stated below $500M by Dec 2025; upGrad merger talks collapsed Jan 2026', 'Cautionary benchmark: ~$860M raised and a $3.44B peak, then a 85%+ valuation reset when Covid-era demand and burn normalized', 'Gaurav Munjal started Unacademy as a YouTube channel in 2010 while a college student in Mumbai, formalizing it in 2015 with Roman Saini — a doctor who cracked UPSC and quit the IAS — and Hemesh Singh. It became edtech royalty in the ZIRP era before a brutal, instructive markdown.', 'Study it alongside PhysicsWallah: same market, opposite capital strategies — a lesson in how burn rate, not TAM, decides who survives.', 'https://indianstartupnews.com/news/yes-we-are-in-ma-talksour-valuation-is-now-less-than-500-million-unacademys-gaurav-munjal-10900450', '2026-08'),
  ('SolarSquare', 'climate', 'Residential rooftop solar', 2015, 'Mumbai', 'growth', 60000000, '$40M Series B led by Lightspeed with Lightrock — one of India''s largest solar VC deals', '2024-12', null, 'Undisclosed', 'Expanding from 20 to 50+ cities on the back of the PM Surya Ghar rooftop-solar subsidy wave; backed by Lightspeed, Elevation, Lowercarbon and Rainmatter (Zerodha)', 'IIT Bombay alumni Shreya Mishra, Nikhil Nahar and Neeraj Jain ran a B2B commercial solar business for six years before betting the company on residential rooftop solar as a consumer brand in 2021 — turning an EPC contractor into a climate-tech startup.', 'Shows how policy tailwinds (rooftop subsidies) plus a consumer-brand lens can transform a ''boring'' engineering services niche into venture-scale climate tech.', 'https://entrackr.com/news/solarsquare-raises-40-mn-in-series-b-led-by-lightspeed-8431566', '2026-08'),
  ('Battery Smart', 'climate', 'Battery-swapping network for electric 2W/3W', 2019, 'Gurugram', 'growth', 157000000, '$65M Series B led by LeapFrog Investments (with MUFG, Panasonic, BII, Blume)', '2024-06', null, 'Undisclosed', 'India''s largest battery-swapping network: 1,000+ partner-run swap stations, 35M+ swaps completed, 45,000+ vehicles served across 30+ cities', 'IIT Kanpur classmates Pulkit Khurana and Siddharth Sikka founded Battery Smart in 2019 on an asset-light insight: let local shopkeepers run franchise swap stations so e-rickshaw drivers exchange a drained battery for a charged one in minutes, no charging downtime.', 'A classic systems-thinking startup: they won EV infrastructure not with better batteries but with a better network and franchise model.', 'https://leapfroginvest.com/press-release/battery-smart-raises-65m-series-b-round-led-by-leapfrog-investments/', '2026-08'),
  ('Qure.ai', 'healthtech', 'AI radiology & diagnostic imaging', 2016, 'Mumbai', 'growth', 123000000, '$65M Series D led by Lightspeed and 360 ONE Asset (with Merck GHI, Kae Capital)', '2024-09', 268000000, '~Rs 2,230 Cr (~$268M) est. (late 2024)', 'The world''s most-deployed healthcare AI: 3,000+ care sites in 90+ countries, FDA clearances across 18 indications; named to TIME''s Most Influential Companies 2025', 'Data scientist Prashant Warier and physician-researcher Dr Pooja Rao spun Qure.ai out of Fractal Analytics in 2016, training deep-learning models to read chest X-rays and CT scans in under a minute — taking radiology expertise to clinics that have none.', 'The best Indian example of AI + medicine as a global export: a Mumbai team''s models now screen for TB and stroke on five continents.', 'https://radiologybusiness.com/topics/artificial-intelligence/radiology-vendor-qureai-completes-65m-series-d-funding-round', '2026-08')
